import type { CSSObject } from '@emotion/react';
import emotionStyled from '@emotion/styled';

import { theme } from '../../../theme';
import type { CardBorder, CardElevation } from './Card';

const elevationStyles: Record<CardElevation, string> = {
  minimal: '0 0 0 0.0625rem rgba(0, 0, 0, 0.16)',
  small: '0 0.125rem 0.5rem 0 rgba(0, 0, 0, 0.08)',
  medium: '0 0.25rem 1rem 0 rgba(0, 0, 0, 0.16)',
  large: '0 0.5rem 1.5rem 0 rgba(0, 0, 0, 0.16)',
  xlarge: '0 1rem 2rem 0 rgba(0, 0, 0, 0.16)',
};

const borderStyles: Record<CardBorder, string> = {
  none: theme.borderRadius.none,
  small: theme.borderRadius['2'],
  medium: theme.borderRadius['4'],
  large: theme.borderRadius['6'],
};

export const StyledCard = emotionStyled('div')<{
  $border: CardBorder;
  $css?: CSSObject;
  $elevated: CardElevation;
}>(({ $border, $css, $elevated }) => ({
  backgroundColor: theme.colors.neutral0,
  borderRadius: borderStyles[$border],
  boxShadow: elevationStyles[$elevated],
  display: 'flex',
  flexDirection: 'column',
  ...$css,
}));
